SELECT DISTINCT DATE_FORMAT(N.DTNEG, '%Y-%m') AS ID, CONCAT('01/', DATE_FORMAT(N.DTNEG, '%m/%Y'), ' - ', CASE MONTH(N.DTNEG) WHEN 1 THEN 'Janeiro' WHEN 2 THEN 'Fevereiro' WHEN 3 THEN 'Março' WHEN 4 THEN 'Abril' WHEN 5 THEN 'Maio' WHEN 6 THEN 'Junho' WHEN 7 THEN 'Julho' WHEN 8 THEN 'Agosto' WHEN 9 THEN 'Setembro' WHEN 10 THEN 'Outubro' WHEN 11 THEN 'Novembro' WHEN 12 THEN 'Dezembro' END, ' ', YEAR(N.DTNEG)) AS PERIODO FROM IMP_NOTAS_ARMAZ N WHERE N.CODPARC = :VAR_PARCEIRO_SELECIONADO ORDER BY ID DESC